from pathlib import Path
import sys

paths=[Path(p) for p in sys.argv[1:]] or [Path('/tmp/a2-pwa/www/app.html')]
if not paths[0].exists() and not sys.argv[1:]:paths=[Path('www/app.html')]

CSS=r'''<style id="a2-dashboard-v6">
.v6-hero{padding:19px;background:radial-gradient(circle at 92% 12%,#0c573c,#08291e 45%,#041811);border:1px solid #2ce49744;border-radius:20px}.v6-hero h3{font-size:28px;margin:5px 0}.v6-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.v6-kpi{padding:16px;border-radius:16px;background:#071e17;border:1px solid #35d99533}.v6-kpi b{display:block;font-size:23px;margin-top:6px}.v6-kpi.red b{color:#ff716b}.v6-kpi.blue b{color:#61c2ff}.v6-strip{display:grid;grid-template-columns:1.2fr repeat(4,.65fr);align-items:center;gap:10px;margin-top:12px}.v6-strip>div{text-align:center}.v6-strip>div:first-child{text-align:left}.v6-meals{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.v6-meal{padding:15px;border-radius:15px;background:#07241a;border:1px solid #27d98c44}.v6-meal b{font-size:17px}.v6-meal strong{display:block;font-size:25px;margin:9px 0}.v6-alerts{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin-top:12px}.v6-alert{cursor:pointer}.v6-alert.danger{border-color:#ff625f88!important}.v6-alert.warn{border-color:#f7c84b88!important}.v6-quick{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:12px}.v6-quick button{min-height:82px}.v6-progress{height:9px;background:#ffffff12;border-radius:99px;overflow:hidden;margin-top:10px}.v6-progress i{display:block;height:100%;background:linear-gradient(90deg,#10d97e,#55efb0);border-radius:99px}@media(max-width:680px){.v6-kpis{grid-template-columns:1fr}.v6-strip{grid-template-columns:repeat(4,1fr)}.v6-strip>div:first-child{grid-column:1/-1;text-align:left}.v6-meals{grid-template-columns:1fr 1fr 1fr}.v6-alerts{grid-template-columns:1fr 1fr}.v6-quick{grid-template-columns:1fr 1fr}.v6-meal{padding:11px}.v6-meal strong{font-size:20px}}
</style>'''

DASH=r'''function dashboard(){const month=currentBillingMonth(),g=globalPaymentSummary(month),today=typeof uaeDateKey==='function'?uaeDateKey(0):new Date().toISOString().slice(0,10),name=state.profile.name||'Admin';if(state.profile.role==='member'){const m=linkedMember(auth.currentUser.uid);if(!m)return`<div class=card style="margin-top:14px"><h3>Member account not linked</h3><p class=muted>Ask Admin to link this login to your member record.</p></div>`;const q=memberSummary(m,month),pct=q.plan?Math.min(100,q.paid/q.plan*100):0,ownSkips=(state.data.mealSkips||[]).filter(x=>x.uid===auth.currentUser.uid&&x.date===today&&x.status==='SKIPPED');return`<div class=v6-hero><div class=small>Welcome back 👋</div><h3>${esc(name)}</h3><div class=small>Monthly Member · ${month}</div></div><div class=v6-kpis><div class=v6-kpi><small>Plan</small><b>AED ${money(q.plan)}</b></div><div class="v6-kpi blue"><small>Paid</small><b>AED ${money(q.paid)}</b></div><div class="v6-kpi red"><small>Due</small><b>AED ${money(q.due)}</b></div></div><div class=card style="margin-top:12px"><div class=top><b>Payment Progress</b><b>${pct.toFixed(0)}%</b></div><div class=v6-progress><i style="width:${pct}%"></i></div></div><div class=card style="margin-top:12px"><div class=top><b>Meal Status Today</b><button class=btn onclick="go('skipmeal')">Skip Meal</button></div><div class=v6-meals>${['Breakfast','Lunch','Dinner'].map(x=>`<div class=v6-meal><b>${x}</b><strong>${ownSkips.some(s=>s.meal===x)?'Skipped':'Needed'}</strong></div>`).join('')}</div></div>`}const summaries=state.data.members.map(m=>memberSummary(m,month)),paid=summaries.filter(x=>x.status==='PAID').length,partial=summaries.filter(x=>x.status==='PARTIAL').length,due=summaries.filter(x=>x.status==='DUE').length,active=state.data.members.filter(x=>x.active!==false).length,low=state.data.inventory.filter(x=>Number(x.qty||0)<=Number(x.min||0)).length,skips=(state.data.mealSkips||[]).filter(x=>x.date===today&&x.status==='SKIPPED').length,pct=g.receivable?Math.min(100,g.received/g.receivable*100):0,total=state.data.members.length,meal=(slot,icon)=>{const skipped=(state.data.mealSkips||[]).filter(x=>x.date===today&&x.meal===slot&&x.status==='SKIPPED').length;return`<div class=v6-meal><b>${icon} ${slot}</b><strong>${Math.max(0,active-skipped)} / ${active}</strong><small class=muted>Meals planned</small></div>`};return`<div class=v6-hero><div class=top><div><div class=small>Good Morning!</div><h3>${esc(name)} 👋</h3><div class=small>${today}</div></div><span class=tag>♛ ADMIN</span></div></div><div class=v6-kpis><div class=v6-kpi><small>Total Receivable</small><b>AED ${money(g.receivable)}</b><small class=muted>Expected from members</small></div><div class="v6-kpi blue"><small>Collected</small><b>AED ${money(g.received)}</b><div class=v6-progress><i style="width:${pct}%"></i></div></div><div class="v6-kpi red"><small>Due</small><b>AED ${money(g.balance)}</b><small class=muted>${(100-pct).toFixed(0)}% pending</small></div></div><div class="card v6-strip"><div><b>👥 Members</b></div><div><b>${total}</b><small class=muted>Total</small></div><div><b>${active}</b><small class=muted>Active</small></div><div><b>${partial}</b><small class=muted>Partial</small></div><div><b>${due}</b><small class=muted>Due</small></div></div><div class=card style="margin-top:12px"><div class=top><b>🍴 Today’s Meal Preparation</b><button class=ghost onclick="go('meals')">View Plan ›</button></div><div class=v6-meals>${meal('Breakfast','☀️')}${meal('Lunch','🔵')}${meal('Dinner','🌙')}</div></div><div class=v6-alerts><div class="card v6-alert danger" onclick="go('skipmeal')"><div class=small>Meal Skips Today</div><div class=metric>${skips}</div><small>View kitchen count ›</small></div><div class="card v6-alert warn" onclick="go('inventory')"><div class=small>Low Inventory</div><div class=metric>${low}</div><small>Items below threshold ›</small></div></div><div class=card style="margin-top:12px"><b>⚡ Quick Actions</b><div class=v6-quick><button class=btn onclick="expenseForm()">＋ Add Expense</button><button class=ghost onclick="go('inventory')">▣ Inventory</button><button class=ghost onclick="go('members')">👥 Members</button><button class=ghost onclick="go('reports')">▥ Reports</button></div></div><div class=card style="margin-top:12px"><div class=top><b>Recent Activity</b><small class=muted>Live cloud data</small></div><div class=row><span>Collection status updated</span><span>${pct.toFixed(0)}% collected</span></div></div>`}'''

for app in paths:
    s=app.read_text()
    if 'id="a2-dashboard-v6"' not in s:s=s.replace('</head>',CSS+'\n</head>',1)
    a=s.find('function dashboard(){');b=s.find('\nfunction linkedMemberForUser',a)
    if a<0 or b<0:raise SystemExit('Dashboard markers missing')
    s=s[:a]+DASH+s[b:]
    required=['a2-dashboard-v6','Total Receivable','Today’s Meal Preparation','Meal Skips Today','Low Inventory','Recent Activity']
    missing=[x for x in required if x not in s]
    if missing:raise SystemExit('Dashboard V6 missing: '+', '.join(missing))
    app.write_text(s)
    print('Applied A2 dashboard V6 to',app)
